        if action == "BUY" and _now_utc.weekday() == 3:  # Thursday = 3
            _conf_before = sig_dict.get("confidence", 0)
            if _conf_before < 58.0:
                sig_dict = dict(sig_dict)
                sig_dict["confidence"] = round(max(35.0, _conf_before - 3.0), 1)
