        ticker_wrs = app_data.get("adaptive_weights", {}).get("ticker_win_rates", {})
        twr = ticker_wrs.get(ticker)
        if twr is not None:
            if twr < 0.45:
                _effective_conf_floor = max(_effective_conf_floor, 68.0)
            elif twr >= 0.75:
                _effective_conf_floor = min(_effective_conf_floor, 52.0)
