    if action == "BUY" and _month == 10 and _conf < 60:
        return (
            f"October seasonality gate — elevated whipsaw risk, confidence {_conf:.0f}% below 60% threshold",
            sig_dict,
        )

    return None, sig_dict  # all gates passed


