    # ── Minimum profit filter ─────────────────────────────────────────────────
    entry = sig_dict.get("entry")
    target = sig_dict.get("target")
    if entry and target and entry > 0:
        profit_pct = abs(target - entry) / entry * 100
        if profit_pct < 2.0:
            return f"profit {profit_pct:.1f}% < 2.0% minimum", sig_dict

