    # - Baa-10Y: >4.0% hard block; >3.0% and score < 50 blocked (marginal block).
    # - T10Y3M: <0.0% (inverted) and score < 55 blocked (marginal block).
    if action == "BUY":
        _nfci = sig_dict.get("nfci")
        _baa = sig_dict.get("baa10y")
        _t10y3m = sig_dict.get("t10y3m")
        _score = sig_dict.get("score", 0.0)

        # NFCI gates
        if _nfci is not None:
            if _nfci > 0.5:
                return f"NFCI={_nfci:.2f} > 0.5 — financial conditions tight, MR hard block (§14)", sig_dict
            if _nfci > 0.0 and _score < 50:
                return (
                    f"NFCI={_nfci:.2f} > 0.0 and score={_score:.1f} < 50 — financial stress marginal block (§14)",
                    sig_dict,
                )

        # BAA10Y gates
        if _baa is not None:
            if _baa > 4.0:
                return f"Baa-10Y spread={_baa:.2f}% > 4.0% — high credit risk, MR hard block (§14)", sig_dict
            if _baa > 3.0 and _score < 50:
                return (
                    f"Baa-10Y spread={_baa:.2f}% > 3.0% and score={_score:.1f} < 50 — credit stress marginal block (§14)",
                    sig_dict,
                )

        # T10Y3M yield curve inversion gates
        if _t10y3m is not None:
            if _t10y3m < 0.0 and _score < 55:
                return (
                    f"Yield Curve Inverted (T10Y3M={_t10y3m:+.2f}%) and score={_score:.1f} < 55 — recession regime marginal block (§14)",
                    sig_dict,
                )

    # ── Pre-earnings blackout (≤2 trading days) ───────────────────────────────
    dte = sig_dict.get("daysToEarnings")
    if dte is not None and 0 < dte <= 2:
        return f"{dte}d to earnings — pre-earnings hard blackout", sig_dict

    # ── Ex-dividend blackout (0–2 days to ex-div, BUY only) ───────────────────
    # Stock drops by dividend amount on ex-div date — structural, not a panic dip.
    # Only gate BUY; HOLD/SELL are unaffected.
    if action == "BUY":
        _exdiv = sig_dict.get("daysToExDiv")
        if _exdiv is not None and 0 <= _exdiv <= 2:
            return (
                f"Ex-dividend in {_exdiv}d — price drop structural not panic, MR entry blocked",
                sig_dict,
            )

    # ── Sector concentration limit (max 2 BUY per sector per 24h) ────────────
    if sector and action == "BUY":
        from models import Signal

        cutoff = _utcnow_naive() - timedelta(hours=24)
        count = (
            await db.execute(
                select(func.count())
                .select_from(Signal)
                .where(Signal.sector_etf == sector)
                .where(Signal.action == "BUY")
                .where(Signal.is_sent == True)
                .where(Signal.sent_at >= cutoff)
            )
        ).scalar_one()
        if count >= 2:
            return f"sector {sector} already has {count} BUY sends in 24h (max 2)", sig_dict

