    _month = datetime.now(timezone.utc).month
    _conf = sig_dict.get("confidence", 0)
    if action == "BUY" and _month == 9 and _conf < 62:
        return (
            f"September seasonality gate — worst calendar month, confidence {_conf:.0f}% below 62% threshold",
            sig_dict,
        )
