    ticker_as_sector = sig_dict.get("ticker", "")
    if (sector and sector in BLOCKED_SECTORS) or (ticker_as_sector in BLOCKED_SECTORS):
        _blocked_key = sector if (sector and sector in BLOCKED_SECTORS) else ticker_as_sector

