    style = sig_dict.get("style", "swing")
    style_floor = STYLE_CONF_FLOORS.get(style, 70.0)
    if conf < style_floor:
        return (
            f"{style} style disabled/floored — conf {conf:.0f}% < {style_floor:.0f}%",
            sig_dict,
        )

