    if action == "BUY":
        _vix_now = sig_dict.get("vix")
        if _vix_now is not None and _vix_now < 15.0:
            return f"VIX={_vix_now:.1f} < 15 — MR entry suspended in ultra-low vol regime (§54)", sig_dict

