        count = (
            await db.execute(
                select(func.count())
                .select_from(Signal)
                .where(Signal.sector_etf == sector)
                .where(Signal.action == "BUY")
                .where(Signal.is_sent == True)
                .where(Signal.sent_at >= cutoff)
            )
        ).scalar_one()
        if count >= 2:
            return f"sector {sector} already has {count} BUY sends in 24h (max 2)", sig_dict

