    if action == "BUY":
        _ca = sig_dict.get("crossAssetHeadwinds")
        if _ca is not None and _ca >= 3:
            return "3/3 cross-asset macro headwinds (TLT+UUP+XLE) — hard block (§55)", sig_dict

